9	#include "orc-rt/QueueingRunner.h"
10	#include "orc-rt/move_only_function.h"
11	#include "gtest/gtest.h"
12	
13	#include <cstdint>
14	#include <thread>
15	#include <vector>
16	
17	using namespace orc_rt;
18	
19	namespace {
20	
21	// Log of task ids, in the order the tasks ran. Tasks record their own id here
22	// when run, letting tests observe both whether and in what order tasks ran.
23	static std::vector<uint64_t> *RecordingLog = nullptr;
24	
25	class QueueingRunnerTest : public ::testing::Test {
26	protected:
27	  void SetUp() override { RecordingLog = &Log; }
28	  void TearDown() override { RecordingLog = nullptr; }
29	
30	  // Build a task that records the given id in the log when run.
31	  static move_only_function<void()> recordingTask(uint64_t Id) {
32	    return [Id]() { RecordingLog->push_back(Id); };
33	  }
34	
35	  std::vector<uint64_t> Log;
36	  QueueingRunner<>::WorkQueue Q;
37	};
38	
39	TEST_F(QueueingRunnerTest, EnqueueDoesNotRunImmediately) {
40	  QueueingRunner<> R(Q);
41	  R(recordingTask(0));
42	  EXPECT_EQ(Log.size(), 0u) << "Enqueue should not run the task";
43	  // Pop initial task.
44	  EXPECT_TRUE(Q.pop_back())
45	      << "At least one task should be sitting in the queue";
46	  EXPECT_FALSE(Q.pop_back())
47	      << "Exactly one task should have been sitting in the queue";
48	}
49	
50	TEST_F(QueueingRunnerTest, RunFIFOUntilEmpty) {
51	  QueueingRunner R(Q);
52	  for (uint64_t I = 0; I < 3; ++I)
53	    R(recordingTask(I));
54	
55	  QueueingRunner<>::runFIFOUntilEmpty(Q);
56	
57	  ASSERT_EQ(Log.size(), 3u);
58	  EXPECT_EQ(Log[0], 0u);
59	  EXPECT_EQ(Log[1], 1u);
60	  EXPECT_EQ(Log[2], 2u);
61	  EXPECT_FALSE(Q.pop_back()); // Expect queue to be empty.
62	}
63	
64	TEST_F(QueueingRunnerTest, RunLIFOUntilEmpty) {
65	  QueueingRunner R(Q);
66	  for (uint64_t I = 0; I < 3; ++I)
67	    R(recordingTask(I));
68	
69	  QueueingRunner<>::runLIFOUntilEmpty(Q);
70	
71	  ASSERT_EQ(Log.size(), 3u);
72	  EXPECT_EQ(Log[0], 2u);
73	  EXPECT_EQ(Log[1], 1u);
74	  EXPECT_EQ(Log[2], 0u);
75	  EXPECT_FALSE(Q.pop_back()); // Expect queue to be empty.
76	}
77	
78	TEST_F(QueueingRunnerTest, DrainOnEmptyQueueIsNoOp) {
79	  // Both drain helpers should return immediately on an empty queue rather
80	  // than blocking.
81	  QueueingRunner<>::runFIFOUntilEmpty(Q);
82	  QueueingRunner<>::runLIFOUntilEmpty(Q);
83	  EXPECT_EQ(Log.size(), 0u);
84	}
85	
86	TEST_F(QueueingRunnerTest, DrainPicksUpTasksEnqueuedDuringDrain) {
87	  // A task enqueued by a running task should also be drained in the same
88	  // runFIFOUntilEmpty call.
89	  QueueingRunner R(Q);
90	
91	  // The first task enqueues a second task from inside its body.
92	  R([&]() {
93	    RecordingLog->push_back(0);
94	    R(recordingTask(1));
95	  });
96	
97	  QueueingRunner<>::runFIFOUntilEmpty(Q);
98	
99	  ASSERT_EQ(Log.size(), 2u);
100	  EXPECT_EQ(Log[0], 0u);
101	  EXPECT_EQ(Log[1], 1u);
102	}
103	
104	TEST_F(QueueingRunnerTest, ConcurrentProducerAndDrainer) {
105	  // Verify that QueueingRunner's default WorkQueue (SynchronizedDeque)
106	  // tolerates concurrent push from one thread and drain from another.
107	  //
108	  // A producer thread enqueues NumTasks tasks while the main thread spins
109	  // draining the queue. Once the producer has finished enqueueing, the main
110	  // thread joins it and then performs a final drain to pick up any tail of
111	  // tasks enqueued after its last loop iteration.
112	  constexpr uint64_t NumTasks = 1024;
113	
114	  QueueingRunner<> R(Q);
115	
116	  std::thread Producer([&]() {
117	    for (uint64_t I = 0; I < NumTasks; ++I)
118	      R(recordingTask(I));
119	  });
120	
121	  // Drain concurrently with the producer. The drainer doesn't know when the
122	  // producer is done, so we just spin until the producer thread has joined
123	  // (after which a final drain will be definitive).
124	  while (Log.size() < NumTasks) {
125	    QueueingRunner<>::runFIFOUntilEmpty(Q);
126	    std::this_thread::yield();
127	  }
128	
129	  Producer.join();
130	  QueueingRunner<>::runFIFOUntilEmpty(Q); // pick up any tail.
131	
132	  ASSERT_EQ(Log.size(), NumTasks);
133	  // Producer enqueues in order 0..NumTasks; FIFO drain must observe the same
134	  // order. (Concurrent draining doesn't reorder per-producer enqueues for a
135	  // single producer.)
136	  for (uint64_t I = 0; I < NumTasks; ++I)
137	    EXPECT_EQ(Log[I], I);
138	
139	  EXPECT_FALSE(Q.pop_back()) << "Queue should be empty after final drain";
140	}
141	
142	} // namespace
